-- DRAFT 1.6.4: fill only missing first-forge regional material pairs. Five explicit source pairs.
-- 1x chance400000; server applies its rate. Existing rows, including quest/card rows, are preserved.
-- Generated by tools/economy/gen_royal_materials.py. TEST/source/real-client proof and release admission pending.
CREATE TABLE IF NOT EXISTS mapleroot_integration_migrations (
  migration_id varchar(100) PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS royal_materials_060_rows (
  dropperid int NOT NULL,
  itemid    int NOT NULL,
  PRIMARY KEY (dropperid, itemid)
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE royal_materials_060_new (
  dropperid int NOT NULL, itemid int NOT NULL, minimum_quantity int NOT NULL, maximum_quantity int NOT NULL,
  questid int NOT NULL, chance int NOT NULL, PRIMARY KEY (dropperid, itemid));
INSERT INTO royal_materials_060_new (dropperid, itemid, minimum_quantity, maximum_quantity, questid, chance) VALUES
(8210000, 4000625, 1, 1, 0, 400000),
(8210001, 4000626, 1, 1, 0, 400000),
(8210003, 4000627, 1, 1, 0, 400000),
(8210004, 4000628, 1, 1, 0, 400000),
(8210005, 4000629, 1, 1, 0, 400000);

-- record only the pairs not already in drop_data (once recorded, a pair stays recorded on a second run)
INSERT IGNORE INTO royal_materials_060_rows (dropperid, itemid)
SELECT n.dropperid, n.itemid FROM royal_materials_060_new n
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);
INSERT INTO drop_data (dropperid, itemid, minimum_quantity, maximum_quantity, questid, chance)
SELECT n.dropperid, n.itemid, n.minimum_quantity, n.maximum_quantity, n.questid, n.chance
  FROM royal_materials_060_new n JOIN royal_materials_060_rows r ON r.dropperid = n.dropperid AND r.itemid = n.itemid
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);

DROP TEMPORARY TABLE royal_materials_060_new;
INSERT IGNORE INTO mapleroot_integration_migrations(migration_id) VALUES ('060-royal-crafting-materials');
